/** Synthetic native-source fixtures through real loopback HTTP/retention/normalization. No live broker proof. */
class PortfolioCashCustodyTest {
 @TempDir Path directory;HttpServer server;String response;int status=200,cashRequests;
 @BeforeEach void start()throws Exception{
  response=body("1234.56");server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  server.createContext("/oauth/token",x->{var bytes="{\"access_token\":\"cash-test-token\"}".getBytes(StandardCharsets.UTF_8);x.getRequestBody().readAllBytes();x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,bytes.length);x.getResponseBody().write(bytes);x.close();});
  server.createContext("/accounts/TTTEST01/positions",x->{var bytes="{\"data\":{\"items\":[]}}".getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,bytes.length);x.getResponseBody().write(bytes);x.close();});
  server.createContext("/accounts/TTTEST01/balances",x->{cashRequests++;assertThat(x.getRequestMethod()).isEqualTo("GET");assertThat(x.getRequestURI().getQuery()).isEqualTo("currency=USD");assertThat(x.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer cash-test-token");var bytes=response.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(status,bytes.length);x.getResponseBody().write(bytes);x.close();});server.start();
 }
 @AfterEach void stop(){server.stop(0);}
 static String body(String amount){return "{\"data\":{\"account-number\":\"TTTEST01\",\"currency\":\"USD\",\"cash-balance\":\""+amount+"\",\"updated-at\":\"2026-10-14T12:34:56Z\",\"snapshot-date\":\"2026-10-14\",\"derivative-buying-power\":\"9999999\",\"pending-cash\":\"8888888\"}}";}
 TastytradeClient client(){return new TastytradeClient("cash-client","cash-secret","cash-refresh",URI.create("http://127.0.0.1:"+server.getAddress().getPort()),HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build());}
 @Test void retainedCashHasOwnOriginalClockAndPrincipalWithoutBecomingBuyingPower()throws Exception{
  try(var db=new SqliteEvidenceStore(directory.resolve("cash.db").toString())){
   var accounts=new AccountDirectory(db,"");String account=accounts.bind("test","TASTYTRADE","TTTEST01");var old=new PositionReadService(db,JSON);var result=new PositionAcquisition(db,accounts,old,client()).acquire(account,"cash-source");assertThat(result.status()).isEqualTo("ACCEPTED");assertThat(result.result()).contains("OBSERVED");var repo=new PortfolioRepository(db,JSON);var source=new PortfolioSources(repo,JSON,accounts);source.refresh(Set.of(account));var holding=repo.list(Kind.HOLDING,Set.of(account)).getFirst();var value=holding.value();assertThat(value.path("kind").asText()).isEqualTo("CASH");assertThat(value.path("quantity").asText()).isEqualTo("1234.56");assertThat(value.path("observedAt").asText()).isEqualTo("2026-10-14T12:34:56Z");assertThat(value.path("receivedAt").asText()).isNotEqualTo(value.path("observedAt").asText());assertThat(value.at("/reportedMarketValue/asOf").asText()).isEqualTo(value.path("observedAt").asText());assertThat(value.at("/evidence/0/locator/value").asText()).isEqualTo("/data/cash-balance");String artifact=value.at("/evidence/0/artifact/href").asText().substring("/v2/artifacts/".length());assertThat(artifact).isNotEqualTo(result.artifactId());var originals=new BrokerageArtifacts(db,JSON,old,accounts);assertThat(new String(originals.content(account,artifact).orElseThrow(),StandardCharsets.UTF_8)).isEqualTo(response);assertThat(originals.sourceScopes(account,"tastytrade-balances.json",response.getBytes(StandardCharsets.UTF_8)).accountIds()).containsExactly(account);
   var position=repo.list(Kind.POSITION,Set.of(account)).getFirst();var construction=repo.get(position.value().at("/currentConstruction/href").asText()).orElseThrow();var leaf=leaves(construction.value().path("composition")).getFirst();assertThat(leaf.path("kind").asText()).isEqualTo("CASH");assertThat(construction.value().at("/recognition/status").asText()).isEqualTo("VALIDATED");assertThat(leaf.at("/allocation/basis/value").asText()).isEqualTo("1234.56");assertThat(leaf.at("/economics/openingCashFlow/status").asText()).isEqualTo("NOT_APPLICABLE");assertThat(leaf.at("/allocation/availability").asText()).isEqualTo("UNKNOWN");var reconciliation=new PortfolioReconciliation(repo).calculate(account,Instant.now());assertThat(reconciliation.path("coverage").asText()).isEqualTo("COMPLETE_CURRENT_ALLOCATIONS");assertThat(reconciliation.at("/balances/0/allocated").asText()).isEqualTo("1234.56");assertThat(reconciliation.at("/balances/0/residual").asText()).isEqualTo("0");assertThat(reconciliation.at("/balances/0/availability").asText()).isEqualTo("UNKNOWN");var summary=new PortfolioSnapshots(repo).summary(new PortfolioSnapshots(repo).current(account).orElseThrow());assertThat(summary.path("holdingCount").asInt()).isEqualTo(1);assertThat(summary.path("evidence")).hasSize(2);assertThat(summary.path("qualifications").toString()).contains("separate source/receipt clocks");source.refresh(Set.of(account));assertThat(repo.list(Kind.HOLDING,Set.of(account))).hasSize(1);assertThat(repo.list(Kind.POSITION,Set.of(account))).hasSize(1);assertThat(cashRequests).isEqualTo(1);
   capture(holding.uri(),value);capture(construction.uri(),construction.value());capture(position.uri(),position.value());capture("/v2/accounts/"+account+"/inventory-reconciliation",reconciliation);
  }
 }
 @Test void actualHttpCustodyAndRecognitionProjectionsRespectIndependentGrants()throws Exception{
  try(var db=new SqliteEvidenceStore(directory.resolve("cash-auth.db").toString())){
   var accounts=new AccountDirectory(db,"");String account=accounts.bind("test","TASTYTRADE","TTTEST01");new PositionAcquisition(db,accounts,new PositionReadService(db,JSON),client()).acquire(account,"source");var repo=new PortfolioRepository(db,JSON);var sources=new PortfolioSources(repo,JSON,accounts);sources.refresh(Set.of(account));var holding=repo.list(Kind.HOLDING,Set.of(account)).getFirst();var construction=repo.list(Kind.CONSTRUCTION,Set.of(account)).getFirst();var position=repo.list(Kind.POSITION,Set.of(account)).getFirst();
   var auth=TestAuthentication.auth("custody=custody:account.holdings.read:"+account+"|account.artifacts.read:"+account+",position=position:account.positions.read:"+account+",both=both:account.positions.read:"+account+"|account.holdings.read:"+account+"|account.artifacts.read:"+account+",foreign=foreign:account.holdings.read:"+accounts.bind("foreign","TASTYTRADE","TTOTHER02"));var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(new PortfolioController(new PortfolioReadService(repo,sources),auth,accounts),new ArtifactsController(new BrokerageArtifacts(db,JSON,new PositionReadService(db,JSON),accounts),auth,JSON)).build();
   String artifact=holding.value().at("/evidence/0/artifact/href").asText();var raw=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(artifact+"/content").header("Authorization","Bearer custody")).andReturn().getResponse();assertThat(raw.getStatus()).isEqualTo(200);assertThat(raw.getContentAsString()).isEqualTo(response);assertThat(raw.getHeader("Content-Disposition")).isEqualTo("attachment");
   var metadata=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(artifact).header("Authorization","Bearer custody")).andReturn().getResponse();assertThat(metadata.getStatus()).isEqualTo(200);var retained=JSON.readTree(metadata.getContentAsString());assertThat(retained.at("/imports/0/fileType").asText()).isEqualTo("API_BALANCES");capture(artifact,retained);
   for(String denied:List.of("position","foreign")){var deniedOriginal=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(artifact+"/content").header("Authorization","Bearer "+denied)).andReturn().getResponse();assertThat(deniedOriginal.getStatus()).isIn(403,404);assertThat(deniedOriginal.getContentAsString()).doesNotContain("9999999","2026-10-14T12:34:56Z");}
   for(String projection:List.of("summary","expanded")){
    var custody=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/v2/holdings?projection="+projection).header("Authorization","Bearer custody")).andReturn().getResponse();assertThat(custody.getStatus()).isEqualTo(200);assertThat(JSON.readTree(custody.getContentAsString()).at("/items/0/quantity").asText()).isEqualTo("1234.56");
    var restricted=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/v2/constructions?projection="+projection).header("Authorization","Bearer position")).andReturn().getResponse();assertThat(restricted.getStatus()).isEqualTo(200);var body=JSON.readTree(restricted.getContentAsString());if(projection.equals("expanded")){assertThat(body.at("/items/0/recognition/status").asText()).isEqualTo("UNCLASSIFIED");assertThat(body.at("/items/0/recognition/reasonCodes").toString()).contains("ACCESS_RESTRICTED");assertThat(body.toString()).doesNotContain(holding.value().at("/evidence/0/artifact/href").asText());}capture("/v2/constructions?projection="+projection,body);
   }
   for(String token:List.of("position","foreign"))assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(holding.uri()).header("Authorization","Bearer "+token)).andReturn().getResponse().getStatus()).isEqualTo(404);
   var allowed=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(construction.uri()).header("Authorization","Bearer both")).andReturn().getResponse();assertThat(allowed.getStatus()).isEqualTo(200);assertThat(JSON.readTree(allowed.getContentAsString()).at("/recognition/status").asText()).isEqualTo("VALIDATED");capture(construction.uri(),JSON.readTree(allowed.getContentAsString()));
   var principal=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(position.uri()).header("Authorization","Bearer position")).andReturn().getResponse();assertThat(principal.getStatus()).isEqualTo(200);var body=JSON.readTree(principal.getContentAsString());assertThat(body.at("/evaluation/marketValue/value").asText()).isEqualTo("1234.56");assertThat(body.at("/evaluation/grossUnrealizedPl/status").asText()).isEqualTo("NOT_APPLICABLE");capture(position.uri(),body);assertThat(cashRequests).isEqualTo(1);
  }
 }
 @Test void missingCashDoesNotUseBuyingPowerAndFailuresDoNotErasePriorEvidence()throws Exception{
  try(var db=new SqliteEvidenceStore(directory.resolve("partial.db").toString())){
   var accounts=new AccountDirectory(db,"");String account=accounts.bind("test","TASTYTRADE","TTTEST01");var old=new PositionReadService(db,JSON);var acquisition=new PositionAcquisition(db,accounts,old,client());var repo=new PortfolioRepository(db,JSON);var source=new PortfolioSources(repo,JSON,accounts);
   acquisition.acquire(account,"first");source.refresh(Set.of(account));var known=repo.list(Kind.HOLDING,Set.of(account)).getFirst();response=body("1").replace("\"cash-balance\":\"1\",","");acquisition.acquire(account,"missing");source.refresh(Set.of(account));var current=new PortfolioSnapshots(repo).current(account).orElseThrow();var partial=repo.list(Kind.HOLDING,Set.of(account)).stream().filter(h->h.snapshot().equals(current.snapshotId())).findFirst().orElseThrow();assertThat(partial.value().path("quantity").isNull()).isTrue();assertThat(partial.value().path("side").asText()).isEqualTo("UNKNOWN");assertThat(partial.value().at("/reportedMarketValue/value").isNull()).isTrue();assertThat(new PortfolioReconciliation(repo).calculate(account,Instant.now()).path("coverage").asText()).isEqualTo("INCOMPLETE");assertThat(repo.list(Kind.POSITION,Set.of(account))).hasSize(1).allSatisfy(p->assertThat(p.value().at("/exposure/status").asText()).isEqualTo("RETAINED"));var retainedPosition=repo.list(Kind.POSITION,Set.of(account)).getFirst();var retainedView=new PortfolioReadService(repo,source).read(retainedPosition,new BearerAuthenticator.Principal("reader",Set.of("account.positions.read:"+account)),Instant.now());assertThat(retainedView.at("/evaluation/marketValue/value").isNull()).isTrue();capture(partial.uri(),partial.value());
   for(String bad:List.of(body("1").replace("TTTEST01","OTHER"),body("1").replace("USD","EUR"),body("not-a-decimal"))){response=bad;var result=acquisition.acquire(account,"reject");assertThat(result.status()).isEqualTo("ACCEPTED");assertThat(result.result()).contains("REJECTED");source.refresh(Set.of(account));assertThat(new PortfolioReconciliation(repo).calculate(account,Instant.now()).path("coverage").asText()).isEqualTo("INCOMPLETE");assertThat(repo.get(known.uri()).orElseThrow().value()).isEqualTo(known.value());}
   status=503;assertThat(acquisition.acquire(account,"unavailable").result()).contains("FAILED");source.refresh(Set.of(account));assertThat(new PortfolioReconciliation(repo).calculate(account,Instant.now()).path("warnings").toString()).contains("settled-cash evidence is FAILED");
  }
 }
 @Test void zeroAndNegativeCashNeverBecomePositiveOwnedCashOrCoverage()throws Exception{
  for(String amount:List.of("0","-200.25"))try(var db=new SqliteEvidenceStore(directory.resolve("cash"+amount+".db").toString())){
   var accounts=new AccountDirectory(db,"");String account=accounts.bind("test","TASTYTRADE","TTTEST01");response=body(amount);new PositionAcquisition(db,accounts,new PositionReadService(db,JSON),client()).acquire(account,"signed");var repo=new PortfolioRepository(db,JSON);new PortfolioSources(repo,JSON,accounts).refresh(Set.of(account));var holding=repo.list(Kind.HOLDING,Set.of(account)).getFirst();assertThat(holding.value().path("quantity").asText()).isEqualTo(amount.equals("0")?"0":"200.25");assertThat(holding.value().path("side").asText()).isEqualTo(amount.equals("0")?"LONG":"SHORT");assertThat(holding.value().at("/reportedMarketValue/value").asText()).isEqualTo(amount);assertThat(repo.list(Kind.POSITION,Set.of(account))).isEmpty();assertThat(new PortfolioReconciliation(repo).calculate(account,Instant.now()).path("coverageAssessments")).isEmpty();capture(holding.uri(),holding.value());
  }
 }
 @Test void cashClockDoesNotBecomeReceiptWhenSourceClockIsMissingOrFuture()throws Exception{
  for(String clock:List.of("bad","2099-01-01T00:00:00Z")){var bytes=body("10").replace("2026-10-14T12:34:56Z",clock).getBytes(StandardCharsets.UTF_8);var result=TastytradeCashBalance.parse(bytes,"TTTEST01",UUID.randomUUID().toString(),"2026-10-21T00:00:00Z");assertThat(result.observedAt()).isNull();assertThat(result.receivedAt()).isEqualTo("2026-10-21T00:00:00Z");}
 }
 static void capture(String path,com.fasterxml.jackson.databind.JsonNode body)throws Exception{var dir=Path.of("build/portfolio-responses");Files.createDirectories(dir);var n=obj().put("path",path).put("caller","synthetic-cash-source-test");n.set("body",body);Files.writeString(dir.resolve(UUID.randomUUID()+".json"),n.toString());}
}
